mapper.sql:
from sys_access_log a
left join sys_prog p on p.prog_cd = a.prog_cd
left join sys_user u on u.user_id = a.user_id
where a.occurred_at >= #{q.from} and a.occurred_at < #{q.to}

    and a.event_cd in #{e}

and a.severity = #{q.severity}
and a.result_cd = #{q.resultCd}
and a.login_id ilike #{q.loginLike} escape '\'
and a.ip like #{q.ipLike} escape '\'
and u.user_type = #{q.userType}
and a.client_type = #{q.clientType}

from sys_audit_log x
where x.occurred_at >= #{q.from} and x.occurred_at < #{q.to}

    and x.table_nm in
    #{t}

and x.action = #{q.action}
and x.actor ilike #{q.actorLike} escape '\'

mapper.select:
select x.audit_id, x.occurred_at, x.table_nm, x.row_key, x.action, x.actor

order by x.occurred_at desc, x.audit_id desc
limit #{q.page.size} offset #{q.page.offset}

mapper.sql:
from sys_feedback f
join sys_user u on u.user_id = f.user_id
left join sys_prog p on p.prog_cd = f.prog_cd
where f.created_at >= #{q.from} and f.created_at < #{q.to}
and f.status = #{q.status}
and f.prog_cd = #{q.progCd}

mapper.select:
select 

order by f.created_at desc, f.feedback_id desc
limit #{q.page.size} offset #{q.page.offset}

mapper.update:
update sys_feedback
   set status = #{status},
       handled_by = case when #{status} = 'NEW' then null else #{by} end,
       handled_at = case when #{status} = 'NEW' then null else now() end,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where feedback_id = #{feedbackId} and row_ver = #{rowVer}
